using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BehenianHowlCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Sothis/BehenianHowlCustomDescription", order = 0)]
public class BehenianHowlCustomDescription : SoulHeatBasedCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string actionDescription = (battleAction as BehenianHowlAction).GainSandsOfTimeEffectAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified));
		string localizedString = base.localizationManager.GetLocalizedString("SoulHeatBasedActionMultiplier");
		return Smart.Format(base.localizationManager.GetLocalizedForEach(), actionDescription.RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), localizedString);
	}
}
